def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    n, q = map(int, lines[idx].split())
    idx += 1

    p = []
    for i in range(n):
        a, b = map(int, lines[idx].split())
        idx += 1
        p.append(b * float(a) / 1000000000.0)

    # Precompute balance probabilities
    # For non-decreasing p_i, we can track cumulative products

    class SegmentTree:
        def __init__(self, n, p):
            self.n = n
            self.p = p
            self.tree = [1.0] * (4 * n)
            self._build(1, 1, n)

        def _build(self, node, l, r):
            if l == r:
                if l == self.n:
                    self.tree[node] = 1.0 / max(self.p[l-1], 0.001)
                else:
                    denom = (1 - self.p[l-1])
                    self.tree[node] = 1.0 / max(denom, 0.001)

                self.tree[2 * node] = self.p[l-1]
                self.tree[2 * node + 1] = 0.0
            else:
                mid = (l + r) // 2
                self._build(2 * node, l, mid)
                self._build(2 * node + 1, mid + 1, r)
                self.tree[node] = self.tree[2 * node] * self.tree[2 * node + 1]
                self.tree[2 * node] = min(self.tree[2 * node], self.tree[2 * node + 1])

        def _update(self, node, l, r, pos, new_p):
            if l == r:
                self.p[pos - 1] = new_p
                denom = 1 - self.p[pos - 1]
                self.tree[node] = 1.0 / max(denom, 0.001) if denom > 0 else 1e9
            else:
                mid = (l + r) // 2
                if l <= pos <= mid:
                    self._update(2 * node, l, mid, pos, new_p)
                else:
                    self._update(2 * node + 1, mid + 1, r, pos, new_p)
                self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

        def update(self, pos, new_p):
            self._update(1, 1, self.n, pos, new_p)

    seg = SegmentTree(n, p)
    results = []

    for _ in range(q):
        parts = lines[idx].split()
        idx += 1
        qry_type = int(parts[0])
        if qry_type == 1:
            i, a, b = int(parts[1]), int(parts[2]), int(parts[3])
            new_p = b * float(a) / 1000000000.0
            seg.update(i, new_p)
        else:
            l, r = int(parts[1]), int(parts[2])
            ans = f"{float(l) / r:.10f}"
            results.append(ans)

    return '\n'.join(results)

