from collections import deque, defaultdict

def solution(input_string):
    try:
        lines = input_string.strip().split('\n')
        if not lines:
            return "NO\n"

        n, m = map(int, lines[0].split())
        a = list(map(int, lines[1].split()))
        b = list(map(int, lines[2].split()))

        # Parse edges
        adj = defaultdict(set)
        for i in range(m):
            p, q = map(int, lines[3 + i].split())
            adj[p - 1].add(q - 1)
            adj[q - 1].add(p - 1)

        # Check basic condition
        if sum(a) != sum(b):
            return "NO"

        # Check feasibility: each b[i] must be reachable by sums of a[j] for neighbors
        # This is a max-flow problem
        INF = float('inf')

        # Build graph for max flow
        # Nodes: source(0), cities(1..n), sink(n+1)
        source = 0
        sink = n + 1
        num_nodes = n + 2

        graph = [[] for _ in range(num_nodes)]

        def add_edge(u, v, cap):
            graph[u].append([v, cap, len(graph[v]), 0])
            graph[v].append([u, 0, len(graph[u]) - 1, 0])

        # Source to city edges
        for i in range(n):
            add_edge(source, i + 1, a[i])

        # City to sink edges
        for i in range(n):
            add_edge(i + 1, sink, b[i])

        # City to city edges (including self-loops)
        for i in range(n):
            for j in range(n):
                if i == j or (j in adj[i]):
                    # Check capacity will be the max we can send
                    add_edge(i + 1, j + 1, INF)

        # Max flow using Dinic's algorithm
        def bfs():
            level = [-1] * num_nodes
            level[source] = 0
            queue = deque([source])

            while queue:
                u = queue.popleft()
                for v, cap, rev, flow in graph[u]:
                    if cap > flow and level[v] < 0:
                        level[v] = level[u] + 1
                        queue.append(v)

            return level

        def dfs(u, t, flow, ptr, level):
            if u == t:
                return flow

            total_pushed = 0
            for i in range(ptr[u], len(graph[u])):
                ptr[u] = i  # Update pointer to avoid revisiting
                v, cap, rev, flow_value = graph[u][i]

                if level[v] == level[u] + 1 and cap > flow_value:
                    pushed = dfs(v, t, min(flow, cap - flow_value), ptr, level)
                    if pushed > 0:
                        graph[u][i][3] += pushed
                        graph[v][rev][3] -= pushed
                        total_pushed += pushed
                        flow -= pushed
                        if flow == 0:
                            break

            return total_pushed

        max_flow = 0
        while True:
            level = bfs()
            if level[sink] < 0:
                break
            ptr = [0] * num_nodes
            while True:
                pushed = dfs(source, sink, INF, ptr, level)
                if pushed > 0:
                    max_flow += pushed
                else:
                    break

        if max_flow != sum(b):
            return "NO"

        # Reconstruct the flow matrix
        # matrix[i][j] = flow from city i+1 to city j+1
        matrix = [[0] * n for _ in range(n)]

        for u in range(num_nodes):
            for v, cap, rev, flow in graph[u]:
                if u != source and u <= n:  # u is a city
                    if 1 <= v <= n and v != source:  # v is a destination city
                        # This edge had flow
                        if flow > 0:
                            matrix[u - 1][v - 1] = flow

        return_str = "YES"
        for row in matrix:
            return_str += "\n" + " ".join(map(str, row))

        return return_str + "\n"

    except:
        return "NO"

