    for i in range(1, t + 1):
        parts = lines[i].split()
        x, y = int(parts[0]), int(parts[1])
        queries.append((x, y))

    if n == 0:
        return '\n'.join(['0'] * t)

    ants = defaultdict(int)
    ants[(0, 0)] = n
    active = set([(0, 0)])

    while active:
        pos = active.pop()
        if ants[pos] < 4:
            continue

        ants[pos] -= 4

        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            neighbor = (pos[0] + dx, pos[1] + dy)
            ants[neighbor] += 1
            if ants[neighbor] >= 4 and neighbor not in active:
                active.add(neighbor)

    results = []
    for q in queries:
        results.append(str(ants[q]))
    return '\n'.join(results)

