def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())
    operations = []

    for i in range(1, n + 1):
        parts = lines[i].split()
        t, x_prime, y = int(parts[0]), int(parts[1]), int(parts[2])
        x = x_prime / 100000.0
        operations.append((t, x, y))

    earliest = [-1] * (m + 1)
    reachable = {0}

    for i in range(n):
        t, x, y = operations[i]
        new_reachable = set(reachable)

        for k in list(reachable):
            for a in range(y + 1):
                if t == 1:
                    # Type 1: k := ceil(k + a * x)
                    new_k = math.ceil(k + a * x)
                else:
                    # Type 2: apply k := ceil(k * x) repeatedly a times
                    temp_k = k
                    for _ in range(a):
                        temp_k = math.ceil(temp_k * x)
                    new_k = temp_k

                if new_k <= m:
                    if earliest[new_k] == -1:
                        earliest[new_k] = i + 1
                    new_reachable.add(new_k)

        reachable = new_reachable

    return ' '.join(str(earliest[j]) for j in range(1, m + 1)) + '\n'

