def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "-1"

    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    graph = [[] for _ in range(n + 1)]

    for i in range(m):
        if 2 + i >= len(lines):
            break
        parts = lines[2 + i].split()
        if len(parts) < 3:
            continue
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edge_id = i + 1
        edges.append((u, v, w, edge_id))
        graph[u].append((v, edge_id, w))
        graph[v].append((u, edge_id, w))

    def bfs_check(start, end, blocked):
        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True

        while queue:
            curr = queue.popleft()
            if curr == end:
                return True
            for neighbor, edge_id, weight in graph[curr]:
                if edge_id not in blocked and not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return False

    # Check 0 edges (already disconnected)
    if not bfs_check(s, t, set()):
        return "0\n0\n"

    # Check 1 edge
    min_cost = float('inf')
    best_edge = None

    for i in range(m):
        u, v, w, idx = edges[i]
        if not bfs_check(s, t, {idx}):
            if w < min_cost:
                min_cost = w
                best_edge = idx

    if min_cost != float('inf'):
        return f"{min_cost}\n1\n{best_edge}\n"

    # Check 2 edges with random sampling for efficiency
    min_two_cost = float('inf')
    best_two = None

    num_samples = min(10000, m * (m - 1) // 2)

    for _ in range(num_samples):
        if m < 2:
            continue
        i = random.randint(0, m - 1)
        j = random.randint(0, m - 1)
        if i == j:
            continue
        blocked = {edges[i][3], edges[j][3]}
        if not bfs_check(s, t, blocked):
            cost = edges[i][2] + edges[j][2]
            if cost < min_two_cost:
                min_two_cost = cost
                best_two = sorted([edges[i][3], edges[j][3]])

    if min_two_cost != float('inf'):
        return f"{min_two_cost}\n2\n{best_two}\n"

    # Also try systematic pairs: one from s's neighbors and one from t's neighbors
    s_edges = [(u, v, w, idx) for u, v, w, idx in edges if u == s or v == s]
    t_edges = [(u, v, w, idx) for u, v, w, idx in edges if u == t or v == t]

    for edge1 in s_edges:
        for edge2 in t_edges:
            if edge1[3] != edge2[3]:
                blocked = {edge1[3], edge2[3]}
                if not bfs_check(s, t, blocked):
                    cost = edge1[2] + edge2[2]
                    if cost < min_two_cost:
                        min_two_cost = cost
                        best_two = sorted([edge1[3], edge2[3]])

    if min_two_cost != float('inf'):
        return f"{min_two_cost}\n2\n{best_two}\n"

    return "-1"

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    if n % 2 != 0:
        return '-1\n'

    cost = [[0] * n for _ in range(n)]

    # Parse cost matrix
    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        for k, val in enumerate(parts):
            if k < i:
                j = k
            else:
                j = k + 1
            cost[i][j] = val

    # Build preferences for each city (lower cost = better)
    preferences = []
    for i in range(n):
        pref = []
        for j in range(n):
            if i != j:
                pref.append((cost[i][j], j))
        pref.sort()
        preferences.append([j for _, j in pref])

    # Greedy matching: first try to match each city with their best available option
    match = [-1] * n
    for i in range(n):
        if match[i] != -1:
            continue
        for j in preferences[i]:
            if match[j] == -1:
                match[i] = j
                match[j] = i
                break

    # Check for stability and fix blocking pairs
    # Keep iterating until no changes
    for _ in range(n * n):
        changed = False
        for i in range(n):
            if match[i] != -1:
                current_partner = match[i]
                current_cost = cost[i][current_partner]

                # Check if city i has a preference for an unmatched city,
                # or for a matched city that also prefers i
                for j in preferences[i]:
                    if match[j] == -1:
                        # Found an unmatched city j
                        match[i] = j
                        match[j] = i
                        changed = True
                        break
                    else:
                        # City j is matched
                        if match[j] == i:
                            continue
                        current_partner_j = match[j]
                        current_cost_j = cost[j][current_partner_j]
                        new_cost_j = cost[j][i]
                        # Check if both would prefer each other over current matches
                        if cost[i][j] < current_cost and new_cost_j < current_cost_j:
                            match[i] = j
                            match[j] = i
                            match[current_partner_j] = -1
                            changed = True
                            break
            if changed:
                break

        if not changed:
            break

    # Check if all cities are matched
    for i in range(n):
        if match[i] == -1:
            return '-1\n'

    # Output result
    result = []
    for m in match:
        result.append(str(m + 1))
    return '\n'.join(result) + '\n'

def solution(input_str):
    def is_gp(arr):
        n = len(arr)
        if n == 0:
            return False
        if n <= 1:
            return True

        # All zeros is a valid GP
        if all(x == 0 for x in arr):
            return True

        # If first element is 0, all subsequent elements must be 0
        if arr[0] == 0:
            return False

        ratio = arr[1] / float(arr[0])

        for i in range(2, n):
            if arr[i-1] == 0:
                # If previous is 0 but current isn't, not a GP
                if arr[i] != 0:
                    return False
            else:
                expected = arr[i-1] * ratio
                if abs(arr[i] - expected) > 1e-9:
                    return False

        return True

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].strip().split()))

    if n == 0:
        return '0\n'

    # Check if already a GP
    if is_gp(arr):
        return '0\n'

    # Try removing each element to see if it becomes a GP
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return '1\n'

    return '2\n'


