            elif k + 2 < n and expression[k+1] == '+':
                inc = 'pre'
                i = k + 2
            else:
                i = k + 1
        elif k < n and expression[k] == '+':
            if k + 1 < n and expression[k+1] == '+':
                if k + 2 < n and expression[k+2] == 'a':
                    inc = 'pre'
                    i = k + 3
                else:
                    i = k + 1
            else:
                i = k + 1
        else:
            i += 1

        summands.append((sign, coeff, inc))

    # Sort summands by coefficient ascending to maximize result
    summands.sort(key=lambda x: x[1])

    # Calculate result with sorted order
    result = 0
    current_a = a
    for (sign, coeff, inc_type) in summands:
        if inc_type == 'post':
            value = coeff * current_a
            result += sign * value
            current_a += 1
        else:
            current_a += 1
            value = coeff * current_a
            result += sign * value

    return str(result)

def solution(text):
    lines = text.strip().split('\n')
    if not lines:
        return '\n'

    first_line = lines[0].strip().split()
    if len(first_line) < 2:
        return '\n'

    n, m = int(first_line[0]), int(first_line[1])

    # Read the matrix rows
    matrix = []
    for i in range(1, n + 1):
        if i < len(lines):
            matrix.append(list(lines[i]))
        else:
            matrix.append([''] * m)

    # Helper function to count characters with odd frequencies in a string
    def count_odd(text):
        counts = [0] * 26
        for c in text:
            counts[ord(c) - ord('a')] += 1
        return sum(1 for x in counts if x % 2 == 1)

    count = 0

    # Iterate over all possible submatrices
    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
                    # Check all rows in the submatrix
                    all_rows_ok = True
                    for i in range(r1, r2 + 1):
                        row = ''.join(matrix[i][c1:c2 + 1])
                        if count_odd(row) > 1:
                            all_rows_ok = False
                            break

                    if not all_rows_ok:
                        continue

                    # Check all columns in the submatrix
                    all_cols_ok = True
                    for j in range(c1, c2 + 1):
                        col = ''.join(matrix[i][j] for i in range(r1, r2 + 1))
                        if count_odd(col) > 1:
                            all_cols_ok = False
                            break

                    if all_cols_ok:
                        count += 1

    return str(count) + '\n'

