                            return False

                    return True
        except:
            return False

    # Actually, let me reconsider - we need all rectangles to be equal
    # This means block(0,0) == block(0,1) == block(0,2)... == block(1,0) etc

    # Simpler approach: check that all r*r vertical blocks match
    # and all c*c horizontal blocks match

