def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "NO\n"

    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Map values to their indices
    num_to_idx = {p[i]: i for i in range(n)}

    # Union-Find structure
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry

    # Group numbers that must be in the same set
    for i in range(n):
        x = p[i]

        # Check if a-x exists in input
        y_a = a - x
        if y_a in num_to_idx:
            j = num_to_idx[y_a]
            if i != j:
                union(i, j)

        # Check if b-x exists in input  
        y_b = b - x
        if y_b in num_to_idx:
            j = num_to_idx[y_b]
            if i != j:
                union(i, j)

    # Group by connected components
    component_root_to_nodes = {}
    for i in range(n):
        root = find(i)
        if root not in component_root_to_nodes:
            component_root_to_nodes[root] = []
        component_root_to_nodes[root].append(i)

    # Check validity of each component and assign sets
    result = [0] * n
    for root, nodes in component_root_to_nodes.items():
        # A component can go to set A if all numbers have their a-counterpart in input
        can_go_to_A = True
        for node in nodes:
            x = p[node]
            y_a = a - x
            if y_a not in num_to_idx:
                can_go_to_A = False
                break

        # A component can go to set B if all numbers have their b-counterpart in input
        can_go_to_B = True
        for node in nodes:
            x = p[node]
            y_b = b - x
            if y_b not in num_to_idx:
                can_go_to_B = False
                break

        if not can_go_to_A and not can_go_to_B:
            return "NO\n"

        # Assign to whichever set is valid (if both valid, choose 0/A)
        if can_go_to_A:
            assignment = 0
        else:
            assignment = 1

        for i in range(len(nodes)):
            node = nodes[i]
            result[node] = assignment

    return "YES\n" + " ".join(map(str, result)) + "\n"


