def solution(input_str):
    MOD = 10**9 + 7
    s = input_str.strip()
    n = len(s)
    pos = 0

    def get_char(i):
        return s[i] if i < n else ''

    def is_range_operator(i):
        """Check if position i starts a range l-r"""
        if i >= n or s[i] != '-':
            return False
        # After '-', must have a digit
        return i + 1 < n and s[i + 1].isdigit()

    def parse_number():
        nonlocal pos
        if pos >= n or not s[pos].isdigit():
            return {'val': 0, 'len': 0}

        start = pos
        while pos < n and is_digit(s[pos]):
            pos += 1

        return {'val': int(s[start:pos]), 'len': pos - start if pos > start else 1}

    def is_digit(c):
        return c.isdigit()

    def consume(c):
        nonlocal pos
        if pos < n and s[pos] == c:
            pos += 1
            return True
        return False

    # Compute 10^k mod MOD
    def pow10(k):
        return pow(10, k, MOD)

    # Concatenation: left valueset + right valueset
    def concat(left, right):
        left_val, left_len = left['val'], left['len']
        right_val, right_len = right['val'], right['len']

        shift = pow10(right_len)
        new_val = (left_val * shift + right_val) % MOD
        new_len = left_len + right_len
        return {'val': new_val, 'len': new_len}

    # Concatenate range l to r
    def concat_range(l, r):
        # l_val, r_val are actual values
        l = l['val']
        r = r['val']

        if l > r:
            return {'val': 0, 'len': 0}

        # Group numbers by digit length for efficiency
        def count_digits(x):
            if x == 0:
                return 1
            s = str(x)
            return len(s)

        # Calculate total length
        total_len = sum(count_digits(k) for k in range(l, r + 1))

        # Calculate value by processing from right to left
        result = 0
        multiplier = 1

        for k in reversed(range(l, r + 1)):
            k_str = str(k)
            k_len = len(k_str)
            k_val = int(k_str)

            result = (result + k_val * multiplier) % MOD
            multiplier = (multiplier * pow10(k_len)) % MOD

        return {'val': result, 'len': total_len}

    # Concatenate expression repeated n times
    def concat_repeat(n, expr):
        n_val = n['val']
        expr_val, expr_len = expr['val'], expr['len']

        if n_val == 0:
            return {'val': 0, 'len': 0}

        # Geometric series: val * (10^len + 10^(2*len) + ... + 10^((n-1)*len))
        # = val * (10^len * (1 - (10^len)^(n-1))) / (1 - 10^len) if 10^len != 1

        if expr_len == 0:
            return {'val': n_val % MOD, 'len': 0}

        base = pow10(expr_len)

        if base == 1:
            # Each repetition adds expr_val at same position
            result = (n_val * expr_val) % MOD
            return {'val': result, 'len': n_val * expr_len}

        # Geometric sum: 1 + r + r^2 + ... + r^(n-1) = (r^n - 1) / (r - 1)
        # Multiply by expr_val and shift

        r = base
        r_n = pow(r, n_val, MOD * MOD)  # Need for sum

        # Actually, simpler: result = expr_val * (1 + r + r^2 + ... + r^(n-1))
        #                    = expr_val * (r^n - 1) / (r - 1)

        numerator = (r_n - 1) % MOD
        denominator = (r - 1) % MOD

        # Modular inverse of denominator
        from math import gcd
        if gcd(denominator, MOD) == 1:
            # Fermat's little theorem
            inv = pow(denominator, MOD - 2, MOD)
        else:
            inv = pow(denominator, MOD - 2, MOD)

        geometric_sum = (numerator * inv) % MOD
        full_result = (expr_val * geometric_sum) % MOD

        total_len = n_val * expr_len

        return {'val': full_result, 'len': total_len}

    # Parse term: number | number - number | number (expression)
    def parse_term():
        nonlocal pos

        if pos >= n:
            return {'val': 0, 'len': 0}

        # Check if starts with '('
        if get_char(pos) == '(':
            # Look ahead to find the number before '('
            # The pattern is: digits)
            start = pos

            while pos < n and s[pos].isdigit():
                pos += 1

            # Check if ')' is at current or if there's a valid pattern
            # Actually, (expression) pattern
            num = parse_number_before_paren()
            consume('(')
            expr = parse_expr()
            consume(')')
            return concat_repeat(num, expr)

        # Check for range
        if is_range_operator(pos):
            l = parse_number()
            consume('-')
            r = parse_number()
            return concat_range(l, r)

        # Parse a simple number
        return parse_number()

    def parse_number_before_paren():
        nonlocal pos
        start = pos
        while pos < n and is_digit(s[pos]):
            pos += 1
        return {'val': int(s[start:pos]), 'len': pos - start if pos > start else 1}

    # Parse expression: term + term + ...
    def parse_expr():
        nonlocal pos
        result = parse_term()

        while pos < n and s[pos] == '+':
            consume('+')
            term = parse_term()
            result = concat(result, term)

        return result

    result = parse_expr()
    return str(result['val']) + '\n'

from functools import lru_cache

def solution(n_str):
    n = int(n_str)

    if n == 0:
        return "0"

    @lru_cache(maxsize=None)
    def min_ops(x):
        if x == 0:
            return 0

        # Get digits of x
        digits = set(int(d) for d in str(x))

        min_remaining = float('inf')

        for d in digits:
            if d > 0:  # Can't subtract 0
                remaining = min_ops(x - d)
                min_remaining = min(min_remaining, 1 + remaining)

        return min_remaining

    result = min_ops(n)
    return str(result)

