from typing import List, Tuple

def solution(input_str: str) -> str:
    """
    Solve the Turboplows problem: maximize the number of T-shaped pieces placed
    in an n x m warehouse.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    if n == 0 or m == 0:
        return "0\n" + "\n".join('.' * m for _ in range(n))

    # Define the 4 T-piece orientations (each has 5 cells)
    # Each tuple contains (row_offset, col_offset) for each cell of the T-piece
    orientation0 = [(0, 0), (0, 1), (0, 2), (1, 1), (2, 1)]  # T pointing down
    orientation1 = [(0, 1), (1, 0), (1, 1), (1, 2), (2, 1)]     # T pointing left
    orientation2 = [(1, 0), (1, 1), (1, 2), (0, 1), (2, 1)]     # T pointing right
    orientation3 = [(0, 0), (1, 0), (2, 0), (1, 1), (1, 2)]     # T pointing up

    orientations = [orientation0, orientation1, orientation2, orientation3]

    # Initialize grid with None (empty)
    grid = [[None for _ in range(m)] for _ in range(n)]

    best_count = [0]
    best_grid = grid

    def can_place(offs, r, c):
        """Check if T-piece at (r,c) with offsets fits in empty spaces"""
        for dr, dc in offs:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m) or grid[nr][nc] is not None:
                return False
        return True

    def place_piece(offs, r, c, letter_idx):
        """Place the piece with a letter in the grid"""
        letter = chr(ord('A') + letter_idx)
        for dr, dc in offs:
            grid[r + dr][c + dc] = letter

    def remove_piece(offs, r, c):
        """Remove the piece from the grid"""
        for dr, dc in offs:
            grid[r + dr][c + dc] = None

    def dfs(count):
        """Depth-first search to find optimal piece placement"""
        # Pruning: if even filling rest with all pieces we can't beat current best
        occupied = sum(1 for row in grid for cell in row if cell is not None)
        if (count + (n * m - occupied) // 5) <= best_count[0]:
            return

        # Update best solution if we have a better count
        if count > best_count[0]:
            best_count[0] = count
            best_grid = [row[:] for row in grid]

        # Try all positions for all pieces using backtracking
        for r in range(n):
            for c in range(m):
                for i, offs in enumerate(orientations):
                    if can_place(offs, r, c):
                        place_piece(offs, r, c, count)
                        dfs(count + 1)
                        remove_piece(offs, r, c)

    dfs(0)

    # Build output string
    result_lines = [str(best_count[0])]
    for row in best_grid:
        result_lines.append(''.join(row))
    return '\n'.join(result_lines)

